const r = await tools.exec_command({cmd:"python - <<'PY'
import json, numpy as np
R=json.load(open('data/calibration.json'))
for gamma in [0.7,1,1.2,1.4,1.6]:
 vals=[]; ys=[]
 for z in R:
  e=z['input']; b=e['temperature']; c=e['contrast']; w=e['wavenumber']; n=4096
  x=2*np.pi*np.arange(n)/n; T=b*(1+c*np.cos(w*x)); Tp=-b*c*w*np.sin(w*x)
  pi=1/T; pi/=pi.sum(); C=np.sum(pi*Tp**2/(2*T))
  vals.append(C/gamma);ys.append(z['value'])
 print(gamma, np.mean(((np.array(vals)-ys)/1e-4)**2), np.median(np.array(ys)/np.array(vals)))
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:4000});
text(r.output);

